class Solution:
    def gridIllumination(self, n: int, lamps: List[List[int]], queries: List[List[int]]) -> List[int]:
        on = {(r, c) for r, c in lamps}
        res = []
        for qr, qc in queries:
            lit = 0
            for r, c in on:
                if r == qr or c == qc or r - c == qr - qc or r + c == qr + qc:
                    lit = 1
                    break
            res.append(lit)
            for r in (qr - 1, qr, qr + 1):
                for c in (qc - 1, qc, qc + 1):
                    on.discard((r, c))
        return res

