    public int[] gridIllumination(int n, int[][] lamps, int[][] queries) {
        Set<Long> on = new HashSet<>();
        for (int[] l : lamps) on.add(encode(l[0], l[1]));
        int[] res = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            long qr = queries[i][0], qc = queries[i][1];
            int lit = 0;
            for (long key : on) {
                long r = key / 2000000000L, c = key % 2000000000L;
                if (r == qr || c == qc || r - c == qr - qc || r + c == qr + qc) { lit = 1; break; }
            }
            res[i] = lit;
            for (long dr = -1; dr <= 1; dr++)
                for (long dc = -1; dc <= 1; dc++)
                    on.remove(encode(qr + dr, qc + dc));
        }
        return res;
    }
    private long encode(long r, long c) { return r * 2000000000L + c; }
}

