from collections import defaultdict

class Solution:
    def gridIllumination(self, n: int, lamps: List[List[int]], queries: List[List[int]]) -> List[int]:
        on = {(r, c) for r, c in lamps}
        row, col, diag, anti = defaultdict(int), defaultdict(int), defaultdict(int), defaultdict(int)
        for r, c in on:
            row[r] += 1
            col[c] += 1
            diag[r - c] += 1
            anti[r + c] += 1
        res = []
        for qr, qc in queries:
            res.append(1 if row[qr] or col[qc] or diag[qr - qc] or anti[qr + qc] else 0)
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    r, c = qr + dr, qc + dc
                    if (r, c) in on:
                        on.remove((r, c))
                        row[r] -= 1
                        col[c] -= 1
                        diag[r - c] -= 1
                        anti[r + c] -= 1
        return res

