class Solution {
public:
    vector<int> gridIllumination(int n, vector<vector<int>>& lamps, vector<vector<int>>& queries) {
        unordered_map<long long, int> row, col, diag, anti;
        set<pair<long long, long long>> on;
        auto add = [&](long long r, long long c, int d) {
            row[r] += d; col[c] += d; diag[r - c] += d; anti[r + c] += d;
        };
        for (auto& l : lamps) on.insert({l[0], l[1]});
        for (auto& [r, c] : on) add(r, c, 1);
        vector<int> res;
        for (auto& q : queries) {
            long long qr = q[0], qc = q[1];
            res.push_back(row[qr] || col[qc] || diag[qr - qc] || anti[qr + qc] ? 1 : 0);
            for (long long dr = -1; dr <= 1; dr++)
                for (long long dc = -1; dc <= 1; dc++) {
                    pair<long long, long long> p{qr + dr, qc + dc};
                    if (on.count(p)) { on.erase(p); add(p.first, p.second, -1); }
                }
        }
        return res;
    }
};

