class Solution {
    public int[] gridIllumination(int n, int[][] lamps, int[][] queries) {
        Map<Long, Integer> row = new HashMap<>(), col = new HashMap<>(),
                           diag = new HashMap<>(), anti = new HashMap<>();
        Set<Long> on = new HashSet<>();
        for (int[] l : lamps) on.add(l[0] * 2000000000L + l[1]);
        for (long k : on) {
            long r = k / 2000000000L, c = k % 2000000000L;
            row.merge(r, 1, Integer::sum);
            col.merge(c, 1, Integer::sum);
            diag.merge(r - c, 1, Integer::sum);
            anti.merge(r + c, 1, Integer::sum);
        }
        int[] res = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            long qr = queries[i][0], qc = queries[i][1];
            res[i] = (row.getOrDefault(qr, 0) > 0 || col.getOrDefault(qc, 0) > 0 ||
                      diag.getOrDefault(qr - qc, 0) > 0 || anti.getOrDefault(qr + qc, 0) > 0) ? 1 : 0;
            for (long dr = -1; dr <= 1; dr++)
                for (long dc = -1; dc <= 1; dc++) {
                    long r = qr + dr, c = qc + dc, k = r * 2000000000L + c;
                    if (on.remove(k)) {
                        row.merge(r, -1, Integer::sum);
                        col.merge(c, -1, Integer::sum);
                        diag.merge(r - c, -1, Integer::sum);
                        anti.merge(r + c, -1, Integer::sum);
                    }
                }
        }
        return res;
    }
}

