var gridIllumination = function(n, lamps, queries) {
    const key = (r, c) => r + ',' + c;
    const on = new Set(lamps.map(([r, c]) => key(r, c)));
    const mk = () => new Map();
    const [row, col, diag, anti] = [mk(), mk(), mk(), mk()];
    const bump = (m, k, d) => m.set(k, (m.get(k) || 0) + d);
    for (const k of on) {
        const [r, c] = k.split(',').map(Number);
        bump(row, r, 1); bump(col, c, 1); bump(diag, r - c, 1); bump(anti, r + c, 1);
    }
    const res = [];
    for (const [qr, qc] of queries) {
        res.push((row.get(qr) || col.get(qc) || diag.get(qr - qc) || anti.get(qr + qc)) ? 1 : 0);
        for (let dr = -1; dr <= 1; dr++)
            for (let dc = -1; dc <= 1; dc++) {
                const r = qr + dr, c = qc + dc, k = key(r, c);
                if (on.delete(k)) {
                    bump(row, r, -1); bump(col, c, -1); bump(diag, r - c, -1); bump(anti, r + c, -1);
                }
            }
    }
    return res;
};
